    53→impl BybitWebSocket {
    54→    pub fn new(config: &Config) -> Self {
    55→        Self {
    56→            api_key: config.bybit_api_key.clone(),
    57→            api_secret: config.bybit_api_secret.clone(),
    58→            private_url: config.ws_url().to_string(),
    59→            public_url: config.ws_public_url().to_string(),
    60→        }
    61→    }
    62→
    63→    pub async fn connect_private(&self, tx: mpsc::Sender<WsEvent>) -> Result<()> {
    64→        let (ws_stream, _) = connect_async(&self.private_url).await?;
    65→        let (mut write, mut read) = ws_stream.split();
    66→
    67→        let expires = SystemTime::now()
    68→            .duration_since(UNIX_EPOCH)?
    69→            .as_millis() as u64
    70→            + 10000;
    71→        let sign_str = format!("GET/realtime{}", expires);
    72→        let signature = sign(&self.api_secret, &sign_str);
    73→
    74→        let auth = AuthMessage {
    75→            op: "auth".to_string(),
    76→            args: vec![self.api_key.clone(), expires.to_string(), signature],
    77→        };
    78→        write.send(Message::Text(serde_json::to_string(&auth)?)).await?;
    79→
    80→        let sub = SubscribeMessage {
    81→            op: "subscribe".to_string(),
    82→            args: vec![
    83→                "order".to_string(),
    84→                "position".to_string(),
    85→                "execution".to_string(),
    86→            ],
    87→        };
    88→        write.send(Message::Text(serde_json::to_string(&sub)?)).await?;
    89→
    90→        let _ = tx.send(WsEvent::Connected).await;
    91→
    92→        let _tx_clone = tx.clone();
    93→        tokio::spawn(async move {
    94→            let mut ping_interval = tokio::time::interval(std::time::Duration::from_secs(20));
    95→            loop {
    96→                ping_interval.tick().await;
    97→                if write.send(Message::Text(r#"{"op":"ping"}"#.to_string())).await.is_err() {
    98→                    break;
    99→                }
   100→            }
   101→        });
   102→
   103→        while let Some(msg) = read.next().await {
   104→            match msg {
   105→                Ok(Message::Text(text)) => {
   106→                    if let Ok(ws_msg) = serde_json::from_str::<WsMessage>(&text) {
   107→                        if let Some(topic) = ws_msg.topic {
   108→                            if let Some(data) = ws_msg.data {
   109→                                let event = match topic.as_str() {
   110→                                    "order" => WsEvent::OrderUpdate(data),
   111→                                    "position" => WsEvent::PositionUpdate(data),
   112→                                    "execution" => WsEvent::ExecutionUpdate(data),
   113→                                    _ => continue,
   114→                                };
   115→                                let _ = tx.send(event).await;
   116→                            }
   117→                        }
   118→                    }
   119→                }
   120→                Ok(Message::Close(_)) => {
   121→                    let _ = tx.send(WsEvent::Disconnected).await;
   122→                    break;
   123→                }
   124→                Err(_) => {
   125→                    let _ = tx.send(WsEvent::Disconnected).await;
   126→                    break;
   127→                }
   128→                _ => {}
   129→            }
   130→        }
   131→
   132→        Ok(())
   133→    }
