    15→pub async fn run(config: Config) -> Result<()> {
    16→    let listener = TcpListener::bind(&config.listen_addr).await?;
    17→    let bybit_client = Arc::new(BybitClient::new(&config));
    18→    let bybit_ws = Arc::new(BybitWebSocket::new(&config));
    19→
    20→    tracing::info!("Server listening on {}", config.listen_addr);
    21→
    22→    while let Ok((stream, addr)) = listener.accept().await {
    23→        tracing::info!("New connection from {}", addr);
    24→        let bybit = bybit_client.clone();
    25→        let ws = bybit_ws.clone();
    26→        tokio::spawn(async move {
    27→            if let Err(e) = handle_connection(stream, bybit, ws).await {
    28→                tracing::error!("Connection error: {}", e);
    29→            }
    30→        });
    31→    }
    32→
    33→    Ok(())
    34→}
    35→
    36→async fn handle_connection(
    37→    stream: TcpStream,
    38→    bybit: Arc<BybitClient>,
    39→    bybit_ws: Arc<BybitWebSocket>,
    40→) -> Result<()> {
    41→    let ws_stream = accept_async(stream).await?;
    42→    let (mut write, mut read) = ws_stream.split();
    43→
    44→    let (tx, mut rx) = mpsc::channel::<ServerMessage>(100);
    45→    let handler = ClientHandler::new(bybit);
    46→
    47→    let connected_msg = ServerMessage::new(ServerPayload::Connected);
    48→    write
    49→        .send(Message::Text(serde_json::to_string(&connected_msg)?))
    50→        .await?;
    51→
    52→    let (ws_event_tx, mut ws_event_rx) = mpsc::channel(100);
    53→    let ws_clone = bybit_ws.clone();
    54→    tokio::spawn(async move {
    55→        if let Err(e) = ws_clone.connect_private(ws_event_tx).await {
    56→            tracing::error!("Bybit WS error: {}", e);
    57→        }
    58→    });
    59→
    60→    let tx_clone = tx.clone();
    61→    tokio::spawn(async move {
    62→        while let Some(event) = ws_event_rx.recv().await {
    63→            let msg = match event {
    64→                WsEvent::OrderUpdate(data) => {
    65→                    if let Ok(orders) = serde_json::from_value(data) {
    66→                        Some(ServerMessage::new(ServerPayload::Orders(orders)))
    67→                    } else {
    68→                        None
    69→                    }
    70→                }
    71→                WsEvent::PositionUpdate(data) => {
    72→                    if let Ok(positions) = serde_json::from_value(data) {
    73→                        Some(ServerMessage::new(ServerPayload::Positions(positions)))
    74→                    } else {
    75→                        None
    76→                    }
    77→                }
    78→                _ => None,
    79→            };
    80→            if let Some(msg) = msg {
    81→                let _ = tx_clone.send(msg).await;
    82→            }
    83→        }
    84→    });
    85→
    86→    let (chart_event_tx, mut chart_event_rx) = mpsc::channel::<WsEvent>(100);
    87→    let chart_tx = tx.clone();
    88→    tokio::spawn(async move {
    89→        while let Some(event) = chart_event_rx.recv().await {
    90→            let msg = match event {
    91→                WsEvent::TradeUpdate(data) => {
    92→                    if let Some(trades) = data.as_array() {
    93→                        for trade_data in trades {
    94→                            if let Some(trade) = parse_trade(trade_data) {
    95→                                let _ = chart_tx.send(ServerMessage::new(ServerPayload::TradeUpdate(trade))).await;
    96→                            }
    97→                        }
    98→                    }
    99→                    None
   100→                }
   101→                WsEvent::KlineUpdate(data) => {
   102→                    if let Some(candles) = data.as_array() {
   103→                        if let Some(candle_data) = candles.first() {
   104→                            if let Some(candle) = parse_candle(candle_data) {
   105→                                Some(ServerMessage::new(ServerPayload::CandleUpdate(candle)))
   106→                            } else {
   107→                                None
   108→                            }
   109→                        } else {
   110→                            None
   111→                        }
   112→                    } else {
   113→                        None
   114→                    }
   115→                }
   116→                _ => None,
   117→            };
   118→            if let Some(msg) = msg {
   119→                let _ = chart_tx.send(msg).await;
   120→            }
   121→        }
   122→    });
   123→
   124→    let mut chart_subscription: Option<tokio::task::JoinHandle<()>> = None;
   125→
   126→    let write_task = tokio::spawn(async move {
   127→        while let Some(msg) = rx.recv().await {
   128→            if let Ok(text) = serde_json::to_string(&msg) {
   129→                if write.send(Message::Text(text)).await.is_err() {
   130→                    break;
   131→                }
   132→            }
   133→        }
   134→    });
   135→
   136→    while let Some(msg) = read.next().await {
   137→        match msg {
   138→            Ok(Message::Text(text)) => {
   139→                match serde_json::from_str::<ClientMessage>(&text) {
   140→                    Ok(client_msg) => {
   141→                        if let ClientPayload::SubscribeChart { ref symbol, ref interval } = client_msg.payload {
   142→                            if let Some(handle) = chart_subscription.take() {
   143→                                handle.abort();
   144→                            }
   145→                            let ws = bybit_ws.clone();
   146→                            let sym = symbol.0.clone();
   147→                            let int = interval.clone();
   148→                            let evt_tx = chart_event_tx.clone();
   149→                            chart_subscription = Some(tokio::spawn(async move {
   150→                                tracing::info!("Starting chart subscription for {} {}", sym, int);
   151→                                if let Err(e) = ws.connect_chart(&sym, &int, evt_tx).await {
   152→                                    tracing::error!("Chart WS error: {}", e);
   153→                                }
   154→                            }));
   155→                            let response = ServerMessage::new(ServerPayload::ChartSubscribed).with_request_id(client_msg.id);
   156→                            let _ = tx.send(response).await;
   157→                        } else if let ClientPayload::UnsubscribeChart = client_msg.payload {
   158→                            if let Some(handle) = chart_subscription.take() {
   159→                                handle.abort();
   160→                            }
   161→                            let response = ServerMessage::new(ServerPayload::ChartSubscribed).with_request_id(client_msg.id);
   162→                            let _ = tx.send(response).await;
   163→                        } else {
   164→                            if let Err(e) = handler.handle(client_msg, &tx).await {
   165→                                tracing::error!("Handler error: {}", e);
   166→                            }
   167→                        }
   168→                    }
   169→                    Err(e) => {
   170→                        tracing::warn!("Invalid message: {}", e);
   171→                    }
   172→                }
   173→            }
   174→            Ok(Message::Close(_)) => break,
   175→            Err(e) => {
   176→                tracing::error!("WebSocket error: {}", e);
   177→                break;
   178→            }
   179→            _ => {}
   180→        }
   181→    }
   182→
   183→    if let Some(handle) = chart_subscription.take() {
   184→        handle.abort();
   185→    }
   186→
   187→    write_task.abort();
   188→    Ok(())
   189→}
